def backtrack(n=12):
    used = [False]*n
    seq = []
    diffs_used = set()

    def dfs():
        if len(seq) == n:
            return True
        for v in range(n):
            if not used[v]:
                if seq:
                    d = abs(seq[-1] - v)
                    if d in diffs_used or d < 1 or d > n-1:
                        continue
                    diffs_used.add(d)
                used[v] = True
                seq.append(v)
                if dfs():
                    return True
                seq.pop()
                used[v] = False
                if seq:
                    diffs_used.discard(d)
        return False

    if dfs():
        return seq
    return None

