import time

def search_costas_optimized(n):
    def backtrack(perm, used_rows, vectors):
        if len(perm) == n:
            return perm[:]
        c = len(perm)
        for r in range(n):
            if r in used_rows:
                continue
            ok = True
            new_vectors = []
            for i, prev_r in enumerate(perm):
                dc = c - i
                dr = r - prev_r
                vec = (dc, dr)
                if vec in vectors:
                    ok = False
                    break
                new_vectors.append(vec)
            if not ok:
                continue
            used_rows.add(r)
            for v in new_vectors:
                vectors.add(v)
            result = backtrack(perm + [r], used_rows, vectors)
            if result:
                return result
            used_rows.remove(r)
            for v in new_vectors:
                vectors.remove(v)
        return None
    return backtrack([], set(), set())

