n = 14
fixed_x = {6: 3, 12: 6}
fixed_d = {3: 10, 11: 2}

def solve_backtrack():
    x = [None] * n
    d = [None] * (n-1)

    x[6] = 3
    x[12] = 6
    d[3] = 10
    d[11] = 2

    used_vals = set([3, 6])
    used_diffs = set([10, 2])

    # For efficiency, we'll also track which differences are used.

    def get_possible_values(pos):
        if x[pos] is not None:
            return [x[pos]]
        possible = set(range(n)) - used_vals

        # Constraint from left neighbor if d[pos-1] fixed
        if pos > 0 and d[pos-1] is not None:
            if x[pos-1] is not None:
                vals = set()
                if x[pos-1] + d[pos-1] < n:
                    vals.add(x[pos-1] + d[pos-1])
                if x[pos-1] - d[pos-1] >= 0:
                    vals.add(x[pos-1] - d[pos-1])
                possible &= vals
            # else: can't prune

        # Constraint from right neighbor if d[pos] fixed
        if pos < n-1 and d[pos] is not None:
            if x[pos+1] is not None:
                vals = set()
                if x[pos+1] + d[pos] < n:
                    vals.add(x[pos+1] + d[pos])
                if x[pos+1] - d[pos] >= 0:
                    vals.add(x[pos+1] - d[pos])
                possible &= vals

        # Also, if left neighbor assigned but d[pos-1] not fixed,
        # the difference must be unused and in 1..n-1
        if pos > 0 and x[pos-1] is not None and d[pos-1] is None:
            # val must be such that |val - x[pos-1]| not in used_diffs and in 1..n-1
            # We can filter
            new_possible = set()
            for val in possible:
                diff = abs(val - x[pos-1])
                if diff != 0 and diff < n and diff not in used_diffs:
                    new_possible.add(val)
            possible &= new_possible

        # Similarly for right neighbor
        if pos < n-1 and x[pos+1] is not None and d[pos] is None:
            new_possible = set()
            for val in possible:
                diff = abs(x[pos+1] - val)
                if diff != 0 and diff < n and diff not in used_diffs:
                    new_possible.add(val)
            possible &= new_possible

        return list(possible)

    best_solution = None

    def dfs():
        nonlocal best_solution

        unassigned = [i for i in range(n) if x[i] is None]
        if not unassigned:
            # All assigned, check all differences
            for i in range(n-1):
                if d[i] is None:
                    diff = abs(x[i+1] - x[i])
                    if diff in used_diffs or diff == 0 or diff >= n:
                        return False
                    # We could set d[i] = diff, but we just need a solution
            best_solution = x[:]
            return True

        # Compute domains
        domains = {}
        for pos in unassigned:
            dom = get_possible_values(pos)
            if not dom:
                return False
            domains[pos] = dom

        # Pick most constrained
        pos = min(unassigned, key=lambda p: len(domains[p]))

        for val in domains[pos]:
            # Check consistency with neighbors (already done in get_possible_values, but double-check)
            ok = True
            if pos > 0 and x[pos-1] is not None:
                diff = abs(val - x[pos-1])
                if diff == 0 or diff >= n:
                    ok = False
                elif d[pos-1] is not None and diff != d[pos-1]:
                    ok = False
                elif d[pos-1] is None and diff in used_diffs:
                    ok = False
            if ok and pos < n-1 and x[pos+1] is not None:
                diff = abs(x[pos+1] - val)
                if diff == 0 or diff >= n:
                    ok = False
                elif d[pos] is not None and diff != d[pos]:
                    ok = False
                elif d[pos] is None and diff in used_diffs:
                    ok = False
            if not ok:
                continue

            # Assign
            x[pos] = val
            used_vals.add(val)

            # Update differences
            diffs_added = []
            if pos > 0 and x[pos-1] is not None and d[pos-1] is None:
                diff = abs(val - x[pos-1])
                d[pos-1] = diff
                used_diffs.add(diff)
                diffs_added.append(('d', pos-1))
            if pos < n-1 and x[pos+1] is not None and d[pos] is None:
                diff = abs(x[pos+1] - val)
                d[pos] = diff
                used_diffs.add(diff)
                diffs_added.append(('d', pos))

            if dfs():
                return True

            # Backtrack
            for typ, idx in diffs_added:
                if typ == 'd':
                    used_diffs.remove(d[idx])
                    d[idx] = None
            x[pos] = None
            used_vals.remove(val)

        return False

    if dfs():
        return best_solution
    return None

