def solve_n_queens(n=9, fixed=None):
    # backtracking with pruning
    # fixed: dict row->col
    if fixed is None:
        fixed = {}
    # columns, diag1 (row-col), diag2 (row+col)
    cols = set()
    diag1 = set()
    diag2 = set()
    board = [None] * n

    # place fixed queens
    for r, c in fixed.items():
        if c in cols or (r - c) in diag1 or (r + c) in diag2:
            return None  # conflict
        cols.add(c)
        diag1.add(r - c)
        diag2.add(r + c)
        board[r] = c

    def backtrack(row):
        if row == n:
            return board[:]
        if board[row] is not None:
            return backtrack(row + 1)
        for col in range(n):
            if col not in cols and (row - col) not in diag1 and (row + col) not in diag2:
                # place
                cols.add(col)
                diag1.add(row - col)
                diag2.add(row + col)
                board[row] = col
                res = backtrack(row + 1)
                if res:
                    return res
                # remove
                cols.remove(col)
                diag1.remove(row - col)
                diag2.remove(row + col)
                board[row] = None
        return None

    return backtrack(0)

