from pysat.solvers import Solver
from pysat.formula import CNF
import itertools

n = 11
fixed_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]

all_edges = [(i,j) for i in range(n) for j in range(i+1,n)]
fixed_set = set(fixed_edges)
variable_edges = [e for e in all_edges if e not in fixed_set]
edge_to_var = {e: i+1 for i, e in enumerate(variable_edges)}
var_to_edge = {i+1: e for i, e in enumerate(variable_edges)}
num_vars = len(variable_edges)
print("Number of variable edges:", num_vars)

cnf = CNF()

# Alpha <= 4: for each 5-set, at least one edge
five_sets = list(itertools.combinations(range(n), 5))
print("Number of 5-sets:", len(five_sets))

for S in five_sets:
    clause = []
    for u, v in itertools.combinations(S, 2):
        if (u,v) in fixed_set or (v,u) in fixed_set:
            clause = None
            break
        else:
            clause.append(edge_to_var[(u,v)])
    if clause is not None:
        cnf.append(clause)

print("Clauses for alpha:", len(cnf.clauses))

# Helper: given a set of vertices, return list of literals for edges crossing between two subsets
def crossing_literals(A, B):
    lits = []
    for u in A:
        for v in B:
            if u < v:
                e = (u,v)
            else:
                e = (v,u)
            if e in fixed_set:
                # fixed edge exists, so crossing is guaranteed; no literal needed, clause satisfied
                return None
            else:
                lits.append(edge_to_var[e])
    return lits

# Connectivity: for every partition of V into two non-empty sets, there must be a crossing edge
# We'll encode for each cut size 0, 1, 2.

# Cut size 0: graph must be connected
print("Encoding connectivity (cut size 0)...")
count0 = 0
for mask in range(1, (1<<n)//2):  # avoid duplicate partitions (A vs B)
    A = [i for i in range(n) if mask>>i & 1]
    if not A:
        continue
    B = [i for i in range(n) if not (mask>>i & 1)]
    if not B:
        continue
    lits = crossing_literals(A, B)
    if lits is not None:
        cnf.append(lits)
        count0 += 1
print("Clauses for cut size 0:", count0)

# Cut size 1: for each vertex a, graph \ {a} must be connected
print("Encoding cut size 1...")
count1 = 0
for a in range(n):
    remaining = [v for v in range(n) if v != a]
    # partitions of remaining into two non-empty sets
    for mask in range(1, (1<<len(remaining))//2):
        A = [remaining[i] for i in range(len(remaining)) if mask>>i & 1]
        if not A:
            continue
        B = [remaining[i] for i in range(len(remaining)) if not (mask>>i & 1)]
        if not B:
            continue
        lits = crossing_literals(A, B)
        if lits is not None:
            cnf.append(lits)
            count1 += 1
print("Clauses for cut size 1:", count1)

# Cut size 2: for each pair (a,b), graph \ {a,b} must be connected
print("Encoding cut size 2...")
count2 = 0
for a, b in itertools.combinations(range(n), 2):
    remaining = [v for v in range(n) if v != a and v != b]
    for mask in range(1, (1<<len(remaining))//2):
        A = [remaining[i] for i in range(len(remaining)) if mask>>i & 1]
        if not A:
            continue
        B = [remaining[i] for i in range(len(remaining)) if not (mask>>i & 1)]
        if not B:
